"""USD prim dataclasses for the Lossless Signal Architecture.

Python representation of USD prims with anchor/modulated classification.
CognitivePrim is the base; AnchorPrim and ModulatedPrim specialize it.
"""

from dataclasses import dataclass, field

from src.lossless.constants import ANCHOR_PHASES, PHASES


@dataclass(frozen=True)
class CognitivePrim:
    """Base representation of a USD cognitive prim.

    Attributes:
        name: Prim name (e.g., "ReasoningProtocols")
        phase: Which cascade phase this prim belongs to (e.g., "KNOWLEDGE")
        prim_type: USD prim type - "def" or "over"
        markdown_content: The markdown payload
        priority: Rendering priority (lower = earlier)
        enabled: Whether this prim is active
        source_file: Which USDA file defined this prim
        doc: USD doc string metadata
        attributes: Additional typed attributes from the prim body
    """

    name: str
    phase: str = "DEFAULT"
    prim_type: str = "def"
    markdown_content: str = ""
    priority: int = 50
    enabled: bool = True
    source_file: str = ""
    doc: str = ""
    attributes: tuple = ()  # tuple of (key, value) pairs for immutability

    @property
    def is_anchor(self) -> bool:
        return self.phase in ANCHOR_PHASES

    @property
    def is_modulated(self) -> bool:
        return not self.is_anchor

    @property
    def phase_index(self) -> int:
        """Return the canonical index of this prim's phase."""
        if self.phase in PHASES:
            return PHASES.index(self.phase)
        return len(PHASES)  # unknown phases sort last

    def with_content(self, new_content: str) -> "CognitivePrim":
        """Return a copy with updated markdown content."""
        return CognitivePrim(
            name=self.name,
            phase=self.phase,
            prim_type=self.prim_type,
            markdown_content=new_content,
            priority=self.priority,
            enabled=self.enabled,
            source_file=self.source_file,
            doc=self.doc,
            attributes=self.attributes,
        )


@dataclass(frozen=True)
class AnchorPrim(CognitivePrim):
    """A prim belonging to an anchor phase (immutable under injection).

    Anchor prims are NEVER modified by injection profiles.
    Their content passes through the pipeline unchanged.
    """

    def __post_init__(self):
        if self.phase not in ANCHOR_PHASES:
            raise ValueError(
                f"AnchorPrim phase must be in ANCHOR_PHASES, "
                f"got '{self.phase}'"
            )


@dataclass(frozen=True)
class ModulatedPrim(CognitivePrim):
    """A prim belonging to a modulated phase (gain-modulated by injection).

    Modulated prims can have their rendering adjusted by injection profiles,
    but the clean signal is always preserved and recoverable.
    """

    def __post_init__(self):
        if self.phase in ANCHOR_PHASES:
            raise ValueError(
                f"ModulatedPrim phase must NOT be in ANCHOR_PHASES, "
                f"got '{self.phase}'"
            )


def classify_prim(prim: CognitivePrim) -> CognitivePrim:
    """Classify a generic CognitivePrim into Anchor or Modulated."""
    if prim.phase in ANCHOR_PHASES:
        return AnchorPrim(
            name=prim.name, phase=prim.phase, prim_type=prim.prim_type,
            markdown_content=prim.markdown_content, priority=prim.priority,
            enabled=prim.enabled, source_file=prim.source_file,
            doc=prim.doc, attributes=prim.attributes,
        )
    return ModulatedPrim(
        name=prim.name, phase=prim.phase, prim_type=prim.prim_type,
        markdown_content=prim.markdown_content, priority=prim.priority,
        enabled=prim.enabled, source_file=prim.source_file,
        doc=prim.doc, attributes=prim.attributes,
    )

"""Injection delta computation.

Takes a CleanConversionResult and an injection profile,
produces deltas. Deltas are ADDITIVE, not replacements.
final = clean + alpha * delta

For anchor phases: delta is EMPTY STRING (no modification).
For modulated phases: delta contains gain-annotated metadata.
"""

from dataclasses import dataclass

from src.lossless.constants import ANCHOR_PHASES, PHASES, PROFILES
from src.lossless.injection.gain import compute_gain


@dataclass(frozen=True)
class InjectionDelta:
    """Result of injection delta computation.

    Attributes:
        section_deltas: Phase-name -> markdown delta string.
        gains_applied: Phase-name -> gain value used.
        is_anchor: Phase-name -> whether this phase is anchor.
        profile_name: Which profile was used.
        s_NM: Signal strength used.
    """

    section_deltas: tuple  # tuple of (key, value) pairs
    gains_applied: tuple   # tuple of (key, value) pairs
    is_anchor: tuple       # tuple of (key, value) pairs
    profile_name: str
    s_NM: float

    def get_deltas_dict(self) -> dict:
        return dict(self.section_deltas)

    def get_gains_dict(self) -> dict:
        return dict(self.gains_applied)

    def get_anchor_flags(self) -> dict:
        return dict(self.is_anchor)

    @staticmethod
    def empty() -> "InjectionDelta":
        """Create an empty delta (no injection)."""
        deltas = tuple((p, "") for p in PHASES)
        gains = tuple((p, 1.0) for p in PHASES)
        anchors = tuple((p, p in ANCHOR_PHASES) for p in PHASES)
        return InjectionDelta(
            section_deltas=deltas,
            gains_applied=gains,
            is_anchor=anchors,
            profile_name="none",
            s_NM=0.0,
        )


def compute_delta(
    sections: dict,
    profile_name: str,
) -> InjectionDelta:
    """Compute injection deltas for all sections.

    Args:
        sections: Phase-name -> markdown mapping (from clean conversion).
        profile_name: Injection profile to use.

    Returns:
        InjectionDelta with per-phase deltas.
    """
    if profile_name not in PROFILES:
        raise ValueError(f"Unknown profile: {profile_name}")

    s_NM = PROFILES[profile_name]["s_NM"]

    section_deltas = {}
    gains_applied = {}
    is_anchor_map = {}

    for phase in PHASES:
        is_anchor = phase in ANCHOR_PHASES
        is_anchor_map[phase] = is_anchor
        g = compute_gain(phase, s_NM)
        gains_applied[phase] = g

        if is_anchor or phase not in sections:
            # Anchor phases or missing phases: empty delta
            section_deltas[phase] = ""
        else:
            # Modulated phases: compute delta content
            section_deltas[phase] = _compute_section_delta(
                sections[phase], g, phase, profile_name
            )

    return InjectionDelta(
        section_deltas=tuple(sorted(section_deltas.items())),
        gains_applied=tuple(sorted(gains_applied.items())),
        is_anchor=tuple(sorted(is_anchor_map.items())),
        profile_name=profile_name,
        s_NM=s_NM,
    )


def _compute_section_delta(
    clean_content: str, gain_value: float, phase: str, profile_name: str
) -> str:
    """Compute the delta for a single modulated section.

    The delta is metadata that records how the section should be
    annotated under injection. It does NOT modify the clean content
    directly - that's the combiner's job (Agent 6).

    For now, deltas are injection metadata comments that get appended.
    """
    if abs(gain_value - 1.0) < 1e-12:
        return ""  # No modulation at gain=1.0

    return (
        f"\n<!-- injection: profile={profile_name} "
        f"phase={phase} gain={gain_value:.6f} -->"
    )

"""Cross-expert mixing matrix tracker.

Tracks cross-expert bleeding coefficients.
The mixing matrix starts as identity and records bleeds.
Must remain invertible at all defined profiles.

Uses pure Python (no numpy) to minimize dependencies.
"""

from src.lossless.constants import (
    ANCHOR_PHASES,
    FLOAT_TOLERANCE,
    MAX_CONDITION_NUMBER,
    MODULATED_PHASES,
    PHASES,
)


# Modulated phases in canonical sorted order
_MOD_PHASES = sorted(MODULATED_PHASES)
_MOD_INDEX = {p: i for i, p in enumerate(_MOD_PHASES)}
_N = len(_MOD_PHASES)


class MixingTracker:
    """Tracks cross-expert bleeding in a mixing matrix.

    The matrix is NxN where N = len(MODULATED_PHASES).
    Starts as identity. Bleeds are recorded as off-diagonal entries.

    Properties:
        - det(matrix) > FLOAT_TOLERANCE (always invertible)
        - condition_number < MAX_CONDITION_NUMBER at defined profiles
        - invert(mix(signal)) == signal (within FLOAT_TOLERANCE)
    """

    def __init__(self):
        # Initialize as identity matrix (list of lists)
        self._matrix = [[0.0] * _N for _ in range(_N)]
        for i in range(_N):
            self._matrix[i][i] = 1.0

    def record_bleed(
        self, source_phase: str, target_phase: str, coefficient: float
    ) -> None:
        """Record a cross-expert bleed.

        Args:
            source_phase: Phase bleeding FROM (must be modulated).
            target_phase: Phase bleeding TO (must be modulated).
            coefficient: Bleed amount in [0, 1).

        Raises:
            ValueError: If either phase is anchor or coefficient invalid.
        """
        if source_phase in ANCHOR_PHASES:
            raise ValueError(f"Cannot bleed from anchor phase: {source_phase}")
        if target_phase in ANCHOR_PHASES:
            raise ValueError(f"Cannot bleed to anchor phase: {target_phase}")
        if source_phase not in _MOD_INDEX:
            raise ValueError(f"Unknown modulated phase: {source_phase}")
        if target_phase not in _MOD_INDEX:
            raise ValueError(f"Unknown modulated phase: {target_phase}")
        if coefficient < 0.0 or coefficient >= 1.0:
            raise ValueError(f"Coefficient must be in [0, 1), got {coefficient}")

        src_i = _MOD_INDEX[source_phase]
        tgt_i = _MOD_INDEX[target_phase]
        self._matrix[tgt_i][src_i] += coefficient

    def determinant(self) -> float:
        """Compute matrix determinant using LU decomposition."""
        return _determinant(self._matrix)

    def is_invertible(self) -> bool:
        """Check if the mixing matrix is invertible."""
        return abs(self.determinant()) > FLOAT_TOLERANCE

    def condition_number(self) -> float:
        """Estimate condition number (ratio of max/min singular values).

        Uses a simplified estimate: ||A|| * ||A^-1|| using infinity norms.
        """
        norm_a = _infinity_norm(self._matrix)
        try:
            inv = _invert_matrix(self._matrix)
        except ValueError:
            return float('inf')
        norm_inv = _infinity_norm(inv)
        return norm_a * norm_inv

    def mix(self, signal: list) -> list:
        """Apply mixing matrix to a signal vector."""
        if len(signal) != _N:
            raise ValueError(f"Signal length must be {_N}, got {len(signal)}")
        return _mat_vec_mul(self._matrix, signal)

    def invert(self, mixed_signal: list) -> list:
        """Recover original signal from mixed signal."""
        if len(mixed_signal) != _N:
            raise ValueError(
                f"Signal length must be {_N}, got {len(mixed_signal)}"
            )
        inv = _invert_matrix(self._matrix)
        return _mat_vec_mul(inv, mixed_signal)

    def to_dict(self) -> dict:
        """Serialize for integrity block.

        Returns dict with sorted keys for determinism.
        """
        return {
            "dimensions": _N,
            "determinant": self.determinant(),
            "condition_number": self.condition_number(),
            "is_invertible": self.is_invertible(),
            "phases": _MOD_PHASES,
            "matrix": [row[:] for row in self._matrix],
        }

    def get_matrix_copy(self) -> list:
        """Return a copy of the internal matrix."""
        return [row[:] for row in self._matrix]


# ── Matrix math (pure Python, no numpy) ─────────────────────────────


def _mat_vec_mul(mat: list, vec: list) -> list:
    """Matrix-vector multiplication."""
    n = len(vec)
    result = [0.0] * n
    for i in range(n):
        # Kahan summation for numerical stability
        s = 0.0
        c = 0.0
        for j in range(n):
            y = mat[i][j] * vec[j] - c
            t = s + y
            c = (t - s) - y
            s = t
        result[i] = s
    return result


def _infinity_norm(mat: list) -> float:
    """Infinity norm: max absolute row sum."""
    n = len(mat)
    max_sum = 0.0
    for i in range(n):
        row_sum = sum(abs(mat[i][j]) for j in range(n))
        if row_sum > max_sum:
            max_sum = row_sum
    return max_sum


def _determinant(mat: list) -> float:
    """Compute determinant via LU decomposition."""
    n = len(mat)
    if n == 0:
        return 1.0

    # Copy matrix
    lu = [row[:] for row in mat]
    det = 1.0

    for col in range(n):
        # Partial pivoting
        max_val = abs(lu[col][col])
        max_row = col
        for row in range(col + 1, n):
            if abs(lu[row][col]) > max_val:
                max_val = abs(lu[row][col])
                max_row = row

        if max_row != col:
            lu[col], lu[max_row] = lu[max_row], lu[col]
            det *= -1.0

        if abs(lu[col][col]) < FLOAT_TOLERANCE:
            return 0.0

        det *= lu[col][col]

        for row in range(col + 1, n):
            factor = lu[row][col] / lu[col][col]
            for j in range(col + 1, n):
                lu[row][j] -= factor * lu[col][j]

    return det


def _invert_matrix(mat: list) -> list:
    """Invert matrix using Gauss-Jordan elimination."""
    n = len(mat)
    # Augmented matrix [A | I]
    aug = [mat[i][:] + [1.0 if j == i else 0.0 for j in range(n)]
           for i in range(n)]

    for col in range(n):
        # Partial pivoting
        max_val = abs(aug[col][col])
        max_row = col
        for row in range(col + 1, n):
            if abs(aug[row][col]) > max_val:
                max_val = abs(aug[row][col])
                max_row = row

        if max_val < FLOAT_TOLERANCE:
            raise ValueError("Matrix is singular")

        if max_row != col:
            aug[col], aug[max_row] = aug[max_row], aug[col]

        pivot = aug[col][col]
        for j in range(2 * n):
            aug[col][j] /= pivot

        for row in range(n):
            if row == col:
                continue
            factor = aug[row][col]
            for j in range(2 * n):
                aug[row][j] -= factor * aug[col][j]

    # Extract inverse
    return [aug[i][n:] for i in range(n)]

"""Routing decision provenance tracker.

Records which path dominated each decision, the blend coefficient,
and the clean route for every decision.
"""

from dataclasses import dataclass


@dataclass(frozen=True)
class ProvenanceRecord:
    """Record of a single routing decision.

    Always stores the clean route, even when dissolved dominates.
    """

    signal_hash: str
    clean_selected: tuple  # top phases from clean route
    dissolved_selected: tuple  # top phases from dissolved route
    blend_alpha: float
    dominant_path: str  # "clean" or "dissolved"
    routing_mode: str  # "standard", "dissolved", "integrative"


class ProvenanceTracker:
    """Collects provenance records for all routing decisions."""

    def __init__(self):
        self._records = []

    def record(self, rec: ProvenanceRecord) -> None:
        """Add a provenance record."""
        self._records.append(rec)

    def get_records(self) -> list:
        """Return all records in order."""
        return list(self._records)

    def get_clean_routes(self) -> list:
        """Return all clean route selections."""
        return [r.clean_selected for r in self._records]

    def summary(self) -> dict:
        """Generate provenance summary for integrity block."""
        total = len(self._records)
        if total == 0:
            return {
                "clean_dominant_count": 0,
                "dissolved_dominant_count": 0,
                "total_decisions": 0,
            }

        clean_count = sum(
            1 for r in self._records if r.dominant_path == "clean"
        )
        return {
            "clean_dominant_count": clean_count,
            "dissolved_dominant_count": total - clean_count,
            "total_decisions": total,
        }

