"""Property-based tests for lossless invariants.

Uses Hypothesis to verify mathematical guarantees hold across
continuous ranges of inputs, not just hand-picked samples.
"""

import math

from hypothesis import given, settings, strategies as st

from src.lossless.constants import (
    ANCHOR_PHASES,
    D_MAP,
    FLOAT_TOLERANCE,
    MAX_CONDITION_NUMBER,
    MODULATED_PHASES,
    PHASES,
)
from src.lossless.injection.gain import compute_gain
from src.lossless.injection.mixing import MixingTracker
from src.lossless.injection.state import InjectionState
from src.lossless.routing.cascade import SignalFingerprint, evaluate_cascade


# ── Gain Properties ──────────────────────────────────────────────────


@given(s_NM=st.floats(min_value=0.0, max_value=0.1, allow_nan=False))
def test_gain_anchor_immunity_any_strength(s_NM):
    """Anchor phases return gain=1.0 at ANY injection strength."""
    for phase in sorted(ANCHOR_PHASES):
        assert compute_gain(phase, s_NM) == 1.0


@given(s_NM=st.floats(min_value=0.0, max_value=0.1, allow_nan=False))
def test_gain_modulated_monotonic(s_NM):
    """Gain for modulated phases is always >= 1.0."""
    for phase in sorted(MODULATED_PHASES):
        g = compute_gain(phase, s_NM)
        assert g >= 1.0


@given(s_NM=st.floats(min_value=0.0, max_value=1.0, allow_nan=False))
def test_gain_identity_at_zero_s(s_NM):
    """gain(any_phase, 0.0) == 1.0 (parametric confirmation)."""
    for phase in PHASES:
        assert compute_gain(phase, 0.0) == 1.0


@given(
    s1=st.floats(min_value=0.0, max_value=0.5, allow_nan=False),
    s2=st.floats(min_value=0.0, max_value=0.5, allow_nan=False),
)
def test_gain_modulated_monotonic_in_s(s1, s2):
    """Higher s_NM -> higher or equal gain for modulated phases."""
    if s1 > s2:
